  additions jsonb := $curriculum${"vocabulary":[{"id":"hearmandarin:w00004","hanzi":"吧","pinyin":"ba","meaning":"grammar particle: suggestion or surmise","categoryId":"other","level":2,"languageLevel":"elementary","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00004","traditional":"吧","partOfSpeech":"particle"},{"id":"hearmandarin:w00006","hanzi":"百","pinyin":"bǎi","meaning":"hundred","categoryId":"other","level":2,"languageLevel":"elementary","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00006","traditional":"百","partOfSpeech":"numeral"},{"id":"hearmandarin:w00007","hanzi":"半","pinyin":"bàn","meaning":"half","categoryId":"other","level":3,"languageLevel":"intermediate","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00007","traditional":"半","partOfSpeech":"numeral; adverb"},{"id":"hearmandarin:w00008","hanzi":"包子","pinyin":"bāozi","meaning":"baozi; steamed stuffed bun","categoryId":"other","level":4,"languageLevel":"intermediate","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00008","traditional":"包子","partOfSpeech":"noun"},{"id":"hearmandarin:w00019","hanzi":"超市","pinyin":"chāoshì","meaning":"supermarket","categoryId":"other","level":3,"languageLevel":"intermediate","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00019","traditional":"超市","partOfSpeech":"noun"},{"id":"hearmandarin:w00023","hanzi":"穿","pinyin":"chuān","meaning":"to wear; to put on","categoryId":"actions","level":2,"languageLevel":"elementary","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00023","traditional":"穿","partOfSpeech":"verb"},{"id":"hearmandarin:w00026","hanzi":"大家","pinyin":"dàjiā","meaning":"everyone","categoryId":"other","level":2,"languageLevel":"elementary","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00026","traditional":"大家","partOfSpeech":"pronoun"},{"id":"hearmandarin:w00029","hanzi":"到","pinyin":"dào","meaning":"to arrive; to reach","categoryId":"actions","level":2,"languageLevel":"elementary","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00029","traditional":"到","partOfSpeech":"verb"},{"id":"hearmandarin:w00032","hanzi":"弟弟","pinyin":"dìdi","meaning":"younger brother","categoryId":"people","level":2,"languageLevel":"elementary","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00032","traditional":"弟弟","partOfSpeech":"noun"},{"id":"hearmandarin:w00044","hanzi":"对","pinyin":"duì","meaning":"right; correct; towards, at; a pair","categoryId":"actions","level":2,"languageLevel":"elementary","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00044","traditional":"對","partOfSpeech":"adjective; preposition; verb; measure word"},{"id":"hearmandarin:w00052","hanzi":"房间","pinyin":"fángjiān","meaning":"room","categoryId":"other","level":2,"languageLevel":"elementary","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00052","traditional":"房間","partOfSpeech":"noun"},{"id":"hearmandarin:w00053","hanzi":"非常","pinyin":"fēicháng","meaning":"very; extremely","categoryId":"other","level":2,"languageLevel":"elementary","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00053","traditional":"非常","partOfSpeech":"adverb"},{"id":"hearmandarin:w00055","hanzi":"分","pinyin":"fēn","meaning":"minute; cent; to divide","categoryId":"numbers","level":3,"languageLevel":"intermediate","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00055","traditional":"分","partOfSpeech":"measure word; verb; noun"},{"id":"hearmandarin:w00059","hanzi":"哥哥","pinyin":"gēge","meaning":"older brother","categoryId":"people","level":2,"languageLevel":"elementary","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00059","traditional":"哥哥","partOfSpeech":"noun"},{"id":"hearmandarin:w00061","hanzi":"给","pinyin":"gěi","meaning":"to give; to; for","categoryId":"actions","level":2,"languageLevel":"elementary","difficulty":"balan